#!/bin/bash
set -e
APP_NAME="FlappyBirdX"
PY_FILE="flappybirdx.py"
DIST_DIR="dist"
BUILD_DIR="build"
TARGET="/Applications/${APP_NAME}.app"
# <1:start> write first
cat > flappybirdx.py <<'EOF'
# FlappyBirdX app fa43bd-stable | © Zimo Shi 2025
import tkinter as tk
import random
import time
import os
import sys

# ----------------- helpers -----------------
def res(p):
    if hasattr(sys, "_MEIPASS"):
        return os.path.join(sys._MEIPASS, p)
    return p

# ----------------- config -----------------
WIDTH, HEIGHT = 360, 640
GRAVITY = 0.55
FLAP_V = -8.0
PIPE_SPEED = 2.5
PIPE_GAP = 180
FPS = 60

BIRD_RADIUS = 8
PIPE_HALF_WIDTH = 26

# ----------------- app -----------------
class FlappyBirdX:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title("FlappyBirdX")

        # normal geometry first
        self.root.geometry(f"{WIDTH}x{HEIGHT}+200+120")

        # hide → realize → show (macOS requirement)
        self.root.withdraw()
        self.root.update_idletasks()
        self.root.deiconify()

        # now apply overlay flags
        self.root.overrideredirect(True)      # removes window frame
        self.root.attributes("-topmost", True)

        self.canvas = tk.Canvas(
            self.root, width=WIDTH, height=HEIGHT,
            bg="#5bd15b", highlightthickness=0
        )
        self.canvas.pack()

        # assets
        self.bird_img = tk.PhotoImage(file=res("assets/bird.png")).subsample(10, 10)
        self.pipe_img = tk.PhotoImage(file=res("assets/pipe.png")).subsample(2, 2)

        # state
        self.state = "IDLE"  # IDLE | RUNNING | GAME_OVER
        self.vy = 0
        self.score = 0
        self.last_time = time.time()
        self.fps = 0

        # bird
        self.bird_x = WIDTH // 3
        self.bird_y = HEIGHT // 2
        self.bird_id = self.canvas.create_image(
            self.bird_x, self.bird_y, image=self.bird_img
        )

        # pipes (model + visuals)
        self.pipes = []  # list of dicts

        # UI
        self.text_id = self.canvas.create_text(
            WIDTH // 2, 40,
            fill="white",
            font=("Menlo", 16, "bold"),
            text="CLICK TO START"
        )

        # input
        self.root.bind("<Button-1>", self.flap)
        self.root.bind("<space>", self.flap)
        self.root.bind("q", lambda e: self.root.destroy())

        self.loop()

    # ----------------- game control -----------------
    def reset_game(self):
        self.canvas.delete("pipe")
        self.pipes.clear()

        self.bird_x = WIDTH // 3
        self.bird_y = HEIGHT // 2
        self.vy = 0
        self.score = 0

        self.canvas.coords(self.bird_id, self.bird_x, self.bird_y)
        self.spawn_pipe()

        self.state = "IDLE"

    def flap(self, _=None):
        if self.state in ("IDLE", "GAME_OVER"):
            self.reset_game()
            self.state = "RUNNING"

        self.vy = FLAP_V

    # ----------------- pipes -----------------
    def spawn_pipe(self):
        gap_y = random.randint(140, HEIGHT - 140)
        x = WIDTH + 60

        top_img = self.canvas.create_image(
            x, gap_y - PIPE_GAP // 2,
            image=self.pipe_img, anchor="s", tags="pipe"
        )
        bot_img = self.canvas.create_image(
            x, gap_y + PIPE_GAP // 2,
            image=self.pipe_img, anchor="n", tags="pipe"
        )

        self.pipes.append({
            "x": x,
            "gap_y": gap_y,
            "top": top_img,
            "bottom": bot_img,
            "passed": False,
        })

    # ----------------- collision -----------------
    def bird_bbox(self):
        r = BIRD_RADIUS
        return (
            self.bird_x - r,
            self.bird_y - r,
            self.bird_x + r,
            self.bird_y + r,
        )

    def collide(self):
        bx1, by1, bx2, by2 = self.bird_bbox()

        if by1 < 0 or by2 > HEIGHT:
            return True

        for p in self.pipes:
            px1 = p["x"] - PIPE_HALF_WIDTH
            px2 = p["x"] + PIPE_HALF_WIDTH

            if bx2 > px1 and bx1 < px2:
                gap_top = p["gap_y"] - PIPE_GAP // 2
                gap_bot = p["gap_y"] + PIPE_GAP // 2

                if by1 < gap_top or by2 > gap_bot:
                    return True

        return False

    # ----------------- main loop -----------------
    def loop(self):
        now = time.time()
        dt = now - self.last_time
        self.last_time = now
        if dt > 0:
            self.fps = int(1 / dt)

        if self.state == "RUNNING":
            # bird physics
            self.vy += GRAVITY
            self.bird_y += self.vy
            self.canvas.coords(self.bird_id, self.bird_x, self.bird_y)

            # pipes
            for p in list(self.pipes):
                p["x"] -= PIPE_SPEED
                self.canvas.coords(
                    p["top"], p["x"], p["gap_y"] - PIPE_GAP // 2
                )
                self.canvas.coords(
                    p["bottom"], p["x"], p["gap_y"] + PIPE_GAP // 2
                )

                if not p["passed"] and p["x"] < self.bird_x:
                    p["passed"] = True
                    self.score += 1

                if p["x"] < -80:
                    self.canvas.delete(p["top"])
                    self.canvas.delete(p["bottom"])
                    self.pipes.remove(p)
                    self.spawn_pipe()

            if self.collide():
                self.state = "GAME_OVER"

        # UI
        if self.state == "IDLE":
            self.canvas.itemconfig(self.text_id, text="CLICK TO START")
        elif self.state == "RUNNING":
            self.canvas.itemconfig(self.text_id, text=f"SCORE: {self.score}")
        else:
            self.canvas.itemconfig(
                self.text_id,
                text=f"GAME OVER\nSCORE: {self.score}\nCLICK TO RESTART"
            )

        self.root.after(int(1000 / FPS), self.loop)


# ----------------- run -----------------
if __name__ == "__main__":
    app = FlappyBirdX()
    app.root.mainloop()
EOF
# <1:end>
if ! command -v pyinstaller >/dev/null 2>&1; then
  echo "▶ PyInstaller not found. Installing..."
  python3 -m pip install --user pyinstaller
  export PATH="$HOME/.local/bin:$PATH"
fi
if [ ! -d "assets" ]; then
  # umm dont judge me about this please
  mkdir assets
  base64 -d <<'EOF' -o assets/bird.png

EOF
  base64 -d <<'EOF' -o assets/pipe.png

EOF
fi
echo "▶ Building ${APP_NAME}..."
rm -rf "$DIST_DIR" "$BUILD_DIR" "${APP_NAME}.spec"
pyinstaller \
  --windowed \
  --name "$APP_NAME" \
  --add-data "assets:assets" \
  "$PY_FILE"
echo "▶ Installing to /Applications..."
# <2:start> fallback to sudo if we don't have perms
rm -rf "$TARGET" || sudo rm -rf "$TARGET"
cp -R "${DIST_DIR}/${APP_NAME}.app" /Applications/ || sudo cp -R "${DIST_DIR}/${APP_NAME}.app" /Applications/
xattr -dr com.apple.quarantine "$TARGET" || sudo xattr -dr com.apple.quarantine "$TARGET"
# <2:end>
echo "✅ Installed successfully!"
echo "▶ Open Applications → ${APP_NAME}"
